const TZ = 'America/Argentina/Buenos_Aires';
const HINT = "\n\nEscribí *volver* para la pregunta anterior o *salir* para terminar.";

const fechaTexto = String($('Webhook').first().json.body.mensaje ?? '').trim();
const partes = fechaTexto.split('/');

const invalida = (msg) => [{ json: { fechaInvalida: true, mensaje: msg + HINT } }];

if (partes.length !== 3) {
  return invalida("No entendí la fecha. Por favor escribila en formato DD/MM/AAAA.");
}

const [dia, mes, anio] = partes.map(p => Number(p.trim()));
if (!Number.isInteger(dia) || !Number.isInteger(mes) || !Number.isInteger(anio)) {
  return invalida("No entendí la fecha. Por favor escribila en formato DD/MM/AAAA.");
}

// Validar que la fecha exista de verdad (ej: 31/02/2026 no existe)
const fecha = new Date(anio, mes - 1, dia);
if (fecha.getDate() !== dia || fecha.getMonth() !== mes - 1 || fecha.getFullYear() !== anio) {
  return invalida("Esa fecha no es válida. Por favor escribila en formato DD/MM/AAAA.");
}

// Comparar contra HOY en horario de Argentina (no el del servidor)
const elegida = `${anio}-${String(mes).padStart(2,'0')}-${String(dia).padStart(2,'0')}`;
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: TZ });

if (elegida < hoy) {
  return invalida("Esa fecha ya pasó. Elegí una fecha de hoy en adelante (formato: DD/MM/AAAA).");
}

const diaSemana = fecha.getDay(); // 0 = domingo, 6 = sabado
if (diaSemana === 0 || diaSemana === 6) {
  return invalida("Los fines de semana no atendemos turnos. Por favor elegí un día de lunes a viernes.");
}

return [{ json: { fechaInvalida: false } }];

