  return invalida("No entendí la fecha. Por favor escribila en formato DD/MM/AAAA.");
}

const [dia, mes, anio] = partes.map(p => Number(p.trim()));
if (!Number.isInteger(dia) || !Number.isInteger(mes) || !Number.isInteger(anio)) {
  return invalida("No entendí la fecha. Por favor escribila en formato DD/MM/AAAA.");
}

// Validar que la fecha exista de verdad (ej: 31/02/2026 no existe)
const fecha = new Date(anio, mes - 1, dia);
if (fecha.getDate() !== dia || fecha.getMonth() !== mes - 1 || fecha.getFullYear() !== anio) {
  return invalida("Esa fecha no es válida. Por favor escribila en formato DD/MM/AAAA.");
}

// Comparar contra HOY en horario de Argentina (no el del servidor)
const elegida = `${anio}-${String(mes).padStart(2,'0')}-${String(dia).padStart(2,'0')}`;
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: TZ });

if (elegida < hoy) {
  return invalida("Esa fecha ya pasó. Elegí una fecha de hoy en adelante (formato: DD/MM/AAAA).");
}

const diaSemana = fecha.getDay(); // 0 = domingo, 6 = sabado
if (diaSemana === 0 || diaSemana === 6) {
  return invalida("Los fines de semana no atendemos turnos. Por favor elegí un día de lunes a viernes.");
}

return [{ json: { fechaInvalida: false } }];

// Intercepta las acciones de control ANTES de que el Switch rutee por estado.
// Detecta: la palabra "volver"/"salir", o el numero que en el mapeo guardado
// en `notas` apunta a los centinelas __VOLVER__ / __SALIR__.
const cita = $input.first().json || {};

const bodyMsg = $('Webhook').first().json.body.mensaje;
const raw = (bodyMsg === undefined || bodyMsg === null ? '' : String(bodyMsg)).trim();
const msg = raw.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// estados donde la pregunta se responde con un numero de lista
const ESTADOS_LISTA = ['agendando', 'espaveterinario', 'esphora',
                       'cancelando', 'cancefeho',
                       'reprogramando', 'reprofeho', 'reprehora'];

const PAL_SALIR  = ['salir', 'terminar', 'cancelar todo', 'menu', 'inicio', 'volver al inicio'];
const PAL_VOLVER = ['volver', 'atras', 'volver atras', 'anterior', 'pregunta anterior'];

const estado = cita.estado || '';
let control = 'ninguno';

if (PAL_SALIR.includes(msg)) {
  control = 'salir';
} else if (PAL_VOLVER.includes(msg)) {
  control = 'volver';
} else if (ESTADOS_LISTA.includes(estado) && /^[0-9]+$/.test(msg)) {
  let mapa = {};
  try {
    const p = JSON.parse(cita.notas);
    mapa = (p && p.horarios) ? p.horarios : (p || {});
  } catch (e) {
    mapa = {};
  }
  const val = mapa[msg];
  if (val === '__VOLVER__') control = 'volver';
  else if (val === '__SALIR__') control = 'salir';
}

return [{ json: { ...cita, estado, control }, pairedItem: { item: 0 } }];

